implementation:
size_t RegisterMPCImageFormat(void) {
  MagickInfo
    *magick_info;

  magick_info=AcquireMagickInfo("MPC","Magick Persistent Cache","Magick Persistent Cache image format");
  if (magick_info == (MagickInfo *) NULL)
    return(sizeof(MagickInfo));

  magick_info->decoder=(DecodeImageHandler *) ReadMPCImage;
  magick_info->encoder=(EncodeImageHandler *) WriteMPCImage;
  magick_info->adjoin=MagickTrue;
  (void) SetMagickInfoOption(magick_info,"description","Magick Persistent Cache image format");
  (void) SetMagickInfoOption(magick_info,"module","MPC");

  (void) RegisterMagickInfo(magick_info);
  return(sizeof(MagickInfo));
}
